const goldFlows = `-- name: GoldFlows :many
SELECT reason,
       sum(CASE WHEN delta > 0 THEN delta ELSE 0 END)::bigint AS created,
       sum(CASE WHEN delta < 0 THEN -delta ELSE 0 END)::bigint AS destroyed,
       count(*)::bigint AS entries
FROM app.gold_ledger
WHERE created_at > now() - ($1::int * interval '1 day')
GROUP BY reason
ORDER BY greatest(sum(CASE WHEN delta > 0 THEN delta ELSE 0 END),
                  sum(CASE WHEN delta < 0 THEN -delta ELSE 0 END)) DESC
`

type GoldFlowsRow struct {
	Reason    string
	Created   int64
	Destroyed int64
	Entries   int64
}

// Economy health: what created gold and what destroyed it, by reason.
func (q *Queries) GoldFlows(ctx context.Context, dollar_1 int32) ([]GoldFlowsRow, error) {
	rows, err := q.db.Query(ctx, goldFlows, dollar_1)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []GoldFlowsRow{}
	for rows.Next() {
		var i GoldFlowsRow
		if err := rows.Scan(
			&i.Reason,
			&i.Created,
			&i.Destroyed,
			&i.Entries,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

